    lj: ['V_{\\text{LJ}}(r)=4\\varepsilon\\Big[\\Big(\\frac{\\sigma}{r}\\Big)^{12}-\\Big(\\frac{\\sigma}{r}\\Big)^{6}\\Big]', true],
