      site: [['quantum/physics/index.html', ['量子物理展馆：势箱和谐振子', 'Quantum Physics: box and oscillator']], ['qchem/index.html#play-box', ['游乐场 · 势箱', 'Playground · particle in a box']], ['qchem/index.html#play-tunnel', ['游乐场 · 隧穿', 'Playground · tunnelling']], ['spectra/index.html#m-rovib', ['谱图馆 · 振转光谱', 'Spectra Hall · rovibrational spectra']]],
